import React, {
  useEffect,
  useState,
} from 'react';

import {
  toast,
} from 'react-toastify';

import {
  FiMail,
  FiCheckCircle,
  FiTrash2,
  FiEye,
  FiUser,
  FiClock,
  FiPhone,
  FiInbox,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';

import AdminTable from '../common/AdminTable';
import AdminCard from '../common/AdminCard';
import AdminModal from '../common/AdminModal';

import {
  useLanguage,
} from '../../contexts/LanguageContext';


const AdminMessages = () => {

  const {
    t,
    language,
  } = useLanguage();


  const isKhmer =
    language === 'km';


  const [
    messages,
    setMessages,
  ] = useState([]);


  const [
    loading,
    setLoading,
  ] = useState(true);


  const [
    selectedMessage,
    setSelectedMessage,
  ] = useState(null);


  const [
    modalOpen,
    setModalOpen,
  ] = useState(false);


  useEffect(() => {

    fetchMessages();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  const fetchMessages = async () => {

    try {

      setLoading(true);


      const response =
        await api.get(
          '/api/contact/'
        );


      setMessages(
        Array.isArray(response.data)
          ? response.data
          : []
      );

    } catch (error) {

      console.error(
        'Fetch messages error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          t(
            'messages.loadFailed'
          )
        )
      );

    } finally {

      setLoading(false);

    }

  };


  const handleMarkRead = async (
    id
  ) => {

    try {

      await api.put(
        `/api/contact/${id}/read`
      );


      toast.success(
        t(
          'messages.markedReadSuccess'
        )
      );


      setMessages(
        (currentMessages) =>
          currentMessages.map(
            (message) =>
              message.id === id
                ? {
                    ...message,
                    is_read: true,
                  }
                : message
          )
      );


      setSelectedMessage(
        (currentMessage) => {

          if (
            !currentMessage ||
            currentMessage.id !== id
          ) {

            return currentMessage;

          }


          return {
            ...currentMessage,
            is_read: true,
          };

        }
      );

    } catch (error) {

      console.error(
        'Mark read error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          t(
            'messages.markReadFailed'
          )
        )
      );

    }

  };


  const handleDelete = async (
    id
  ) => {

    const confirmDelete =
      window.confirm(
        t(
          'messages.deleteConfirm'
        )
      );


    if (!confirmDelete) {

      return;

    }


    try {

      await api.delete(
        `/api/contact/${id}`
      );


      toast.success(
        t(
          'messages.deletedSuccess'
        )
      );


      if (
        selectedMessage &&
        selectedMessage.id === id
      ) {

        setModalOpen(false);
        setSelectedMessage(null);

      }


      setMessages(
        (currentMessages) =>
          currentMessages.filter(
            (message) =>
              message.id !== id
          )
      );

    } catch (error) {

      console.error(
        'Delete message error:',
        error
      );


      toast.error(
        getApiErrorMessage(
          error,
          t(
            'messages.deleteFailed'
          )
        )
      );

    }

  };


  const handleView = (
    message
  ) => {

    setSelectedMessage(
      message
    );


    setModalOpen(true);


    if (!message.is_read) {

      handleMarkRead(
        message.id
      );

    }

  };


  const closeModal = () => {

    setModalOpen(false);
    setSelectedMessage(null);

  };


  const unreadCount =
    messages.filter(
      (message) =>
        !message.is_read
    ).length;


  const formatNumber = (
    value
  ) => {

    try {

      return Number(
        value || 0
      ).toLocaleString(
        isKhmer
          ? 'km-KH'
          : 'en-GB'
      );

    } catch {

      return value;

    }

  };


  const formatDate = (
    value
  ) => {

    if (!value) {

      return '-';

    }


    const date =
      new Date(value);


    if (
      Number.isNaN(
        date.getTime()
      )
    ) {

      return '-';

    }


    try {

      return date.toLocaleString(
        isKhmer
          ? 'km-KH'
          : 'en-GB',
        {
          year: 'numeric',
          month: 'short',
          day: 'numeric',
          hour: '2-digit',
          minute: '2-digit',
        }
      );

    } catch {

      return (
        date.toLocaleString()
      );

    }

  };


  const columns = [

    {
      key: 'is_read',

      label:
        t(
          'messages.status'
        ),

      render: (value) => (

        <span
          className={`
            inline-flex
            items-center
            gap-2
            px-3
            py-1.5
            rounded-full
            border
            text-xs
            font-semibold
            ${
              value
                ? `
                  bg-blue-50
                  text-blue-700
                  border-blue-200
                `
                : `
                  bg-red-50
                  text-red-600
                  border-red-200
                `
            }
          `}
        >

          <span
            className={`
              w-2
              h-2
              rounded-full
              ${
                value
                  ? 'bg-blue-500'
                  : 'bg-red-500'
              }
            `}
          />


          {
            value
              ? t(
                  'messages.read'
                )
              : t(
                  'messages.unread'
                )
          }

        </span>

      ),
    },


    {
      key: 'name',

      label:
        t(
          'messages.name'
        ),

      render: (value) => (

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-900
              flex-shrink-0
            "
          >

            <FiUser
              size={17}
            />

          </div>


          <div
            className="
              min-w-0
            "
          >

            <p
              className="
                font-semibold
                text-blue-900
                truncate
              "
            >

              {value || '-'}

            </p>

          </div>

        </div>

      ),
    },


    {
      key: 'email',

      label:
        t(
          'messages.email'
        ),

      render: (value) => (

        <div
          className="
            flex
            items-center
            gap-2
            text-sm
            text-blue-500
          "
        >

          <FiMail
            size={15}

            className="
              text-blue-300
              flex-shrink-0
            "
          />


          <span
            className="
              break-all
            "
          >

            {value || '-'}

          </span>

        </div>

      ),
    },


    {
      key: 'subject',

      label:
        t(
          'messages.subject'
        ),

      render: (value) => (

        <span
          className="
            inline-block
            max-w-[220px]
            truncate
            text-sm
            font-medium
            text-blue-900
          "
        >

          {
            value ||
            t(
              'messages.noSubject'
            )
          }

        </span>

      ),
    },


    {
      key: 'created_at',

      label:
        t(
          'messages.date'
        ),

      render: (value) => (

        <div
          className="
            flex
            items-center
            gap-2
            text-sm
            text-blue-500
            whitespace-nowrap
          "
        >

          <FiClock
            size={14}
            className="text-blue-300"
          />


          {formatDate(value)}

        </div>

      ),
    },


    {
      key: 'actions',

      label:
        t(
          'messages.actions'
        ),

      render: (
        _,
        row
      ) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          <button
            type="button"

            onClick={() =>
              handleView(
                row
              )
            }

            title={
              t(
                'messages.viewMessage'
              )
            }

            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-blue-50
              text-blue-900
              hover:bg-blue-900
              hover:text-white
              transition-all
              duration-200
            "
          >

            <FiEye
              size={16}
            />

          </button>


          {
            !row.is_read && (

              <button
                type="button"

                onClick={() =>
                  handleMarkRead(
                    row.id
                  )
                }

                title={
                  t(
                    'messages.markAsRead'
                  )
                }

                className="
                  w-9
                  h-9
                  flex
                  items-center
                  justify-center
                  rounded-lg
                  bg-blue-50
                  text-blue-600
                  hover:bg-blue-600
                  hover:text-white
                  transition-all
                  duration-200
                "
              >

                <FiCheckCircle
                  size={16}
                />

              </button>

            )
          }


          <button
            type="button"

            onClick={() =>
              handleDelete(
                row.id
              )
            }

            title={
              t(
                'messages.deleteMessage'
              )
            }

            className="
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              bg-red-50
              text-red-600
              hover:bg-red-600
              hover:text-white
              transition-all
              duration-200
            "
          >

            <FiTrash2
              size={16}
            />

          </button>

        </div>

      ),
    },

  ];


  return (

    <div
      className={`
        w-full
        ${
          isKhmer
            ? 'font-khmer'
            : 'font-english'
        }
      `}
    >


      <div
        className="
          flex
          flex-col
          lg:flex-row
          lg:items-center
          lg:justify-between
          gap-4
          mb-7
        "
      >

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-12
              h-12
              flex
              items-center
              justify-center
              rounded-xl
              bg-blue-900
              text-white
              shadow-sm
              flex-shrink-0
            "
          >

            <FiMail
              size={22}
            />

          </div>


          <div>

            <h1
              className="
                text-2xl
                md:text-3xl
                font-bold
                text-blue-900
                leading-tight
              "
            >

              {t(
                'messages.title'
              )}

            </h1>


            <p
              className="
                text-sm
                text-blue-400
                mt-1
              "
            >

              {t(
                'messages.subtitle'
              )}

            </p>

          </div>

        </div>


        <div
          className="
            flex
            flex-wrap
            items-center
            gap-3
          "
        >

          <div
            className="
              inline-flex
              items-center
              gap-2
              h-11
              px-4
              rounded-xl
              bg-red-50
              text-red-600
              border
              border-red-200
              text-sm
              font-semibold
            "
          >

            <span
              className="
                w-2.5
                h-2.5
                rounded-full
                bg-red-500
              "
            />


            {formatNumber(
              unreadCount
            )}{' '}


            {t(
              'messages.unread'
            )}

          </div>


          <div
            className="
              inline-flex
              items-center
              gap-2
              h-11
              px-4
              rounded-xl
              bg-blue-50
              text-blue-900
              border
              border-blue-200
              text-sm
              font-semibold
            "
          >

            <FiInbox
              size={17}
            />


            {formatNumber(
              messages.length
            )}{' '}


            {t(
              'messages.total'
            )}

          </div>

        </div>

      </div>


      <AdminCard
        className="
          overflow-hidden
          bg-white
          border
          border-blue-200
          rounded-2xl
          shadow-sm
        "
      >

        <AdminTable
          columns={
            columns
          }

          data={
            messages
          }

          loading={
            loading
          }
        />

      </AdminCard>


      <AdminModal
        isOpen={
          modalOpen
        }

        onClose={
          closeModal
        }

        title={
          t(
            'messages.details'
          )
        }
      >

        <div
          className={
            isKhmer
              ? 'font-khmer'
              : 'font-english'
          }
        >

          {
            selectedMessage && (

              <div>


                <div
                  className="
                    flex
                    items-center
                    gap-4
                    p-4
                    mb-5
                    rounded-2xl
                    bg-blue-50
                    border
                    border-blue-200
                  "
                >

                  <div
                    className="
                      w-12
                      h-12
                      flex
                      items-center
                      justify-center
                      rounded-xl
                      bg-blue-900
                      text-white
                      flex-shrink-0
                    "
                  >

                    <FiUser
                      size={21}
                    />

                  </div>


                  <div
                    className="
                      min-w-0
                    "
                  >

                    <h3
                      className="
                        text-base
                        font-bold
                        text-blue-900
                        truncate
                      "
                    >

                      {
                        selectedMessage.name ||
                        '-'
                      }

                    </h3>


                    <p
                      className="
                        text-sm
                        text-blue-500
                        truncate
                      "
                    >

                      {
                        selectedMessage.email ||
                        '-'
                      }

                    </p>

                  </div>


                  <div
                    className="
                      ml-auto
                    "
                  >

                    <span
                      className={`
                        inline-flex
                        items-center
                        gap-1.5
                        px-3
                        py-1.5
                        rounded-full
                        border
                        text-xs
                        font-semibold
                        ${
                          selectedMessage.is_read
                            ? `
                              bg-blue-50
                              text-blue-700
                              border-blue-200
                            `
                            : `
                              bg-red-50
                              text-red-600
                              border-red-200
                            `
                        }
                      `}
                    >

                      {
                        selectedMessage.is_read
                          ? (
                            <FiCheckCircle />
                          )
                          : (
                            <FiMail />
                          )
                      }


                      {
                        selectedMessage.is_read
                          ? t(
                              'messages.read'
                            )
                          : t(
                              'messages.unread'
                            )
                      }

                    </span>

                  </div>

                </div>


                <div
                  className="
                    grid
                    grid-cols-1
                    md:grid-cols-2
                    gap-4
                  "
                >

                  <div
                    className="
                      p-4
                      rounded-xl
                      border
                      border-blue-200
                      bg-blue-50
                    "
                  >

                    <p
                      className="
                        text-xs
                        font-semibold
                        uppercase
                        tracking-wide
                        text-blue-300
                        mb-1.5
                      "
                    >

                      {t(
                        'messages.email'
                      )}

                    </p>


                    <div
                      className="
                        flex
                        items-center
                        gap-2
                        text-sm
                        font-medium
                        text-blue-900
                      "
                    >

                      <FiMail
                        className="
                          text-blue-900
                          flex-shrink-0
                        "
                      />


                      <span
                        className="
                          break-all
                        "
                      >

                        {
                          selectedMessage.email ||
                          '-'
                        }

                      </span>

                    </div>

                  </div>


                  <div
                    className="
                      p-4
                      rounded-xl
                      border
                      border-blue-200
                      bg-blue-50
                    "
                  >

                    <p
                      className="
                        text-xs
                        font-semibold
                        uppercase
                        tracking-wide
                        text-blue-300
                        mb-1.5
                      "
                    >

                      {t(
                        'messages.phone'
                      )}

                    </p>


                    <div
                      className="
                        flex
                        items-center
                        gap-2
                        text-sm
                        font-medium
                        text-blue-900
                      "
                    >

                      <FiPhone
                        className="
                          text-blue-900
                          flex-shrink-0
                        "
                      />


                      {
                        selectedMessage.phone ||
                        t(
                          'messages.notProvided'
                        )
                      }

                    </div>

                  </div>

                </div>


                <div
                  className="
                    mt-4
                  "
                >

                  <p
                    className="
                      text-sm
                      font-semibold
                      text-blue-900
                      mb-2
                    "
                  >

                    {t(
                      'messages.subject'
                    )}

                  </p>


                  <div
                    className="
                      px-4
                      py-3
                      rounded-xl
                      bg-blue-50
                      border
                      border-blue-200
                      text-sm
                      font-medium
                      text-blue-900
                    "
                  >

                    {
                      selectedMessage.subject ||
                      t(
                        'messages.noSubject'
                      )
                    }

                  </div>

                </div>


                <div
                  className="
                    mt-4
                  "
                >

                  <p
                    className="
                      text-sm
                      font-semibold
                      text-blue-900
                      mb-2
                    "
                  >

                    {t(
                      'messages.message'
                    )}

                  </p>


                  <div
                    className="
                      min-h-[140px]
                      p-4
                      rounded-xl
                      bg-blue-50
                      border
                      border-blue-200
                      text-sm
                      text-blue-900
                      leading-7
                      whitespace-pre-wrap
                      break-words
                    "
                  >

                    {
                      selectedMessage.message ||
                      t(
                        'messages.noMessage'
                      )
                    }

                  </div>

                </div>


                <div
                  className="
                    mt-4
                    flex
                    items-center
                    gap-2
                    text-xs
                    text-blue-300
                  "
                >

                  <FiClock />


                  {t(
                    'messages.received'
                  )}:


                  <span
                    className="
                      font-medium
                      text-blue-500
                    "
                  >

                    {
                      formatDate(
                        selectedMessage.created_at
                      )
                    }

                  </span>

                </div>


                <div
                  className="
                    mt-7
                    pt-5
                    border-t
                    border-blue-200
                    flex
                    flex-col-reverse
                    sm:flex-row
                    sm:items-center
                    sm:justify-between
                    gap-3
                  "
                >

                  <button
                    type="button"

                    onClick={() =>
                      handleDelete(
                        selectedMessage.id
                      )
                    }

                    className="
                      h-11
                      inline-flex
                      items-center
                      justify-center
                      gap-2
                      px-5
                      rounded-xl
                      bg-red-50
                      text-red-600
                      border
                      border-red-200
                      text-sm
                      font-semibold
                      hover:bg-red-600
                      hover:text-white
                      hover:border-red-600
                      transition-all
                      duration-200
                    "
                  >

                    <FiTrash2
                      size={16}
                    />


                    {t(
                      'messages.deleteMessage'
                    )}

                  </button>


                  <button
                    type="button"

                    onClick={
                      closeModal
                    }

                    className="
                      h-11
                      px-6
                      rounded-xl
                      bg-blue-900
                      hover:bg-blue-700
                      text-white
                      text-sm
                      font-semibold
                      shadow-sm
                      hover:shadow-md
                      transition-all
                      duration-200
                    "
                  >

                    {t(
                      'messages.close'
                    )}

                  </button>

                </div>

              </div>

            )
          }

        </div>

      </AdminModal>

    </div>

  );

};


export default AdminMessages;
